namespace ghidra.plugins.fsbrowser.filehandlers;



using docking.action;
using docking.action.builder;
using ghidra.formats.gfilesystem;
using ghidra.plugins.fsbrowser;

public class OpenFsFSBFileHandler : FSBFileHandler {

	private static readonly string FSB_OPEN_ROOT_FS = "FSB Open My Computer";
	public static readonly string FSB_OPEN_FILE_SYSTEM_CHOOSER = "FSB Open File System Chooser";
	public static readonly string FSB_OPEN_FILE_SYSTEM_IN_NEW_WINDOW =
		"FSB Open File System In New Window";
	public static readonly string FSB_OPEN_DIR_IN_NEW_WINDOW = "FSB Open Directory In New Window";
	public static readonly string FSB_OPEN_FILE_SYSTEM_NESTED = "FSB Open File System Nested";

	private FSBFileHandlerContext context;

	/* @Override */
	public void init(FSBFileHandlerContext context) {
		this.context = context;
	}

	/* @Override */
	public List<DockingAction> createActions() {
		return List.of(
			new ActionBuilder(FSB_OPEN_FILE_SYSTEM_NESTED, context.plugin().getName())
					.withContext(typeof(FSBActionContext))
					.enabledWhen(ac => ac.notBusy() &&
						ac.getSelectedNode() is FSBFileNode fileNode && fileNode.isLeaf() &&
						!fileNode.isSymlink())
					.popupMenuIcon(FSBIcons.OPEN_FILE_SYSTEM)
					.popupMenuPath("Open File System")
					.popupMenuGroup("C")
					.onAction(
						ac => ac.getComponentProvider().openFileSystem(ac.getSelectedNode(), true))
					.build(),

			new ActionBuilder(FSB_OPEN_FILE_SYSTEM_IN_NEW_WINDOW, context.plugin().getName())
					.withContext(typeof(FSBActionContext))
					.enabledWhen(ac => ac.notBusy() &&
						ac.getSelectedNode() is FSBFileNode fileNode && fileNode.isLeaf() &&
						!fileNode.isSymlink())
					.popupMenuIcon(FSBIcons.OPEN_FILE_SYSTEM)
					.popupMenuPath("Open File System [new window]")
					.popupMenuGroup("C")
					.onAction(
						ac => ac.getComponentProvider().openFileSystem(ac.getSelectedNode(), false))
					.build(),

			new ActionBuilder(FSB_OPEN_DIR_IN_NEW_WINDOW, context.plugin().getName())
					.withContext(typeof(FSBActionContext))
					.enabledWhen(ac => ac.notBusy() &&
						ac.getSelectedNode() is FSBDirNode dirNode && !dirNode.isSymlink())
					.popupMenuIcon(FSBIcons.OPEN_FILE_SYSTEM)
					.popupMenuPath("Open Directory [new window]")
					.popupMenuGroup("C")
					.onAction(
						ac => ac.getComponentProvider().openFileSystem(ac.getSelectedNode(), false))
					.build(),

			new ActionBuilder(FSB_OPEN_ROOT_FS, context.plugin().getName())
					.description("Show the 'My Computer' location")
					.enabledWhen(ac => !context.fsbComponent().getGTree().isBusy())
					.toolBarIcon(FSBIcons.MY_COMPUTER)
					.toolBarGroup("B")
					.onAction(ac => {
						FileSystemService fsService = context.fsService();
						context.plugin()
								.createNewFileSystemBrowser(
									fsService.getLocalFS().getRefManager().create(), null, true);
					})
					.build(),

			new ActionBuilder(FSB_OPEN_FILE_SYSTEM_CHOOSER, context.plugin().getName())
					.description("Open File System Chooser")
					.enabledWhen(ac => !context.fsbComponent().getGTree().isBusy())
					.toolBarIcon(FSBIcons.OPEN_FILE_SYSTEM)
					.toolBarGroup("B")
					.onAction(ac => context.plugin().openFileSystem())
					.build());
	}

}
